        catch (e) { log(bot, `Failed to reach item: ${e.message}`); throw e; }
        await sleep(500);
        const prev = nearestItem;
        nearestItem = getNearestItem();
        if (prev === nearestItem && prev.isValid) break;
        pickedUp++;
